insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m3.q1', 'm3', 'single', 'm3.1', 'In Three.js, what does the renderer do?', null, '["Holds all the objects and lights","Draws what the camera sees onto a <canvas>","Decides which part of the world you see","Loads 3D models from files"]'::jsonb, 'Scene = world, camera = eye, renderer = …?', '1'::jsonb, '["That''s the scene: the world that contains everything.","Correct: the renderer turns the camera''s view into pixels on a canvas.","That''s the camera''s job.","Loaders (like GLTFLoader in Module 4) load models. The renderer draws."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m3.q2', 'm3', 'order', 'm3.1', 'Put these lines in order so the cube appears on screen.', null, '["renderer.render(scene, camera);","import * as THREE from ''three'';","scene.add(cube);","const scene = new THREE.Scene();"]'::jsonb, 'Each line needs the one before it.', '[1,3,2,0]'::jsonb, '["Import Three.js first (everything else uses THREE), create the scene, add the cube to it, and only then render: rendering before adding draws an empty world."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m3.q3', 'm3', 'single', 'm3.1', 'Your cube is at (0, 0, 0) and so is your camera. You see nothing. What''s the simplest fix?', null, '["camera.position.z = 4","Make the cube smaller","Add a second scene","Set the canvas background to white"]'::jsonb, 'Everything starts at the centre.', '0'::jsonb, '["Correct: move the camera back so the cube is in front of it.","The camera is inside the cube; a smaller cube is still around the camera.","One scene is enough. The camera needs to step back.","The background colour doesn''t change what the camera can see."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m3.q4', 'm3', 'single', 'm3.2', 'Which line creates a visible object correctly?', null, '["new THREE.Mesh(new THREE.BoxGeometry(), new THREE.MeshStandardMaterial())","new THREE.Geometry(new THREE.Mesh())","new THREE.Material(new THREE.BoxGeometry())","new THREE.Scene(new THREE.BoxGeometry())"]'::jsonb, 'Mesh(shape, surface).', '0'::jsonb, '["Correct: a mesh takes a geometry (shape) and a material (surface).","It''s the other way round: the mesh contains the geometry.","A material doesn''t take a geometry; both go into a Mesh.","A scene is created empty; you add meshes to it with scene.add()."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m3.q5', 'm3', 'single', 'm3.2', 'Spot the bug. Nothing appears on screen. Which line is missing?', '1  const geometry = new THREE.TorusKnotGeometry();
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m3.q6', 'm3', 'single', 'm3.3', 'Your MeshStandardMaterial object is completely black. Why?', null, '["There are no lights in the scene","The camera is too close","The geometry is too simple","The renderer is too small"]'::jsonb, 'What do realistic materials need to be seen?', '0'::jsonb, '["Correct: standard materials only show colour where light hits them.","A close camera still sees colour if there''s light.","Simple shapes still show colour when lit.","Canvas size doesn''t change whether the object is lit."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m3.q7', 'm3', 'single', 'm3.3', 'Which light works like the sun, with parallel rays from one direction?', null, '["AmbientLight","DirectionalLight","PointLight","MeshBasicMaterial"]'::jsonb, 'Think of the sun.', '1'::jsonb, '["Ambient light fills everything evenly, with no direction.","Correct: directional light has parallel rays, like sunlight.","A point light shines outward from one spot, like a bulb.","That''s a material that ignores light, not a light."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m3.q8', 'm3', 'single', 'm3.3', 'Which material ignores lights and always shows its flat colour?', null, '["MeshStandardMaterial","MeshBasicMaterial","MeshPhysicalMaterial","All materials ignore lights"]'::jsonb, 'Its name says it''s the simplest one.', '1'::jsonb, '["Standard material reacts to light: it''s black in the dark.","Correct: Basic material is unlit, one flat colour.","Physical material is even more realistic than standard, so it needs light too.","Most realistic materials depend on light."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m3.q9', 'm3', 'single', 'm3.4', 'What does requestAnimationFrame(animate) do?', null, '["Calls animate once, just before the next screen refresh","Calls animate every second","Records a video of the canvas","Loads the next frame of a 3D model"]'::jsonb, 'It''s how the loop keeps going, frame after frame.', '0'::jsonb, '["Correct: and calling it again inside animate creates a loop.","It follows the screen''s refresh rate (often 60 times a second), not once a second.","It doesn''t record anything.","It''s a browser timing function, not a model loader."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m3.q10', 'm3', 'single', 'm3.4', 'How much is a full turn in Three.js rotation units?', null, '["360","Math.PI * 2","1","100"]'::jsonb, 'Radians, not degrees.', '1'::jsonb, '["Three.js uses radians, not degrees.","Correct: a full turn is 2π radians, about 6.28.","1 radian is about 57 degrees, not a full turn.","Rotation isn''t measured in percent."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m3.q11', 'm3', 'single', 'm3.5', 'Which CSS makes the 3D canvas a full-screen background behind your content?', null, '["canvas { position: fixed; inset: 0; z-index: -1; }","canvas { display: none; }","canvas { width: 50%; }","canvas { position: absolute; z-index: 999; }"]'::jsonb, 'Pinned, full-screen, and behind.', '0'::jsonb, '["Correct: pinned to the window, full screen, behind everything.","That hides the canvas completely.","Half width is still in the page flow, pushing content around.","z-index 999 puts it on top of your content, covering it."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m3.q12', 'm3', 'single', 'm3.5', 'After resizing the window, your 3D scene looks stretched. What did you forget?', null, '["Updating camera.aspect, calling camera.updateProjectionMatrix() and renderer.setSize() on resize","Reloading Three.js","Adding another light","Changing the geometry"]'::jsonb, 'Width ÷ height changed.', '0'::jsonb, '["Correct: the camera and canvas need the new width and height.","Three.js is already loaded; it needs the new size, not a reload.","Lights don''t affect stretching.","The shape is fine; the camera''s aspect ratio is out of date."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
